import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { api, RepoCredential } from '@/lib/api'
import { GitBranch, Plus, Trash2, Key, AlertCircle } from 'lucide-react'
import { toast } from 'sonner'

const PLATFORM_OPTIONS = [
  { value: 'cnb', label: 'CNB (cnb.sh)' },
  { value: 'github', label: 'GitHub' },
  { value: 'gitee', label: 'Gitee' },
  { value: 'gitlab', label: 'GitLab' },
]

const PLATFORM_COLORS: Record<string, string> = {
  cnb: 'bg-blue-500',
  github: 'bg-gray-800',
  gitee: 'bg-red-500',
  gitlab: 'bg-orange-500',
}

export function RepoCredentials() {
  const queryClient = useQueryClient()
  const { data, isLoading } = useQuery({
    queryKey: ['repo-credentials'],
    queryFn: api.getRepoCredentials,
  })
  const credentials = data?.data ?? []

  const [showForm, setShowForm] = useState(false)
  const [platform, setPlatform] = useState('cnb')
  const [orgSlug, setOrgSlug] = useState('')
  const [accessToken, setAccessToken] = useState('')
  const [apiBase, setApiBase] = useState('')
  const [name, setName] = useState('')
  const [submitting, setSubmitting] = useState(false)

  const saveMutation = useMutation({
    mutationFn: api.setRepoCredential,
    onSuccess: () => {
      toast.success('凭据已保存')
      queryClient.invalidateQueries({ queryKey: ['repo-credentials'] })
      resetForm()
    },
    onError: (e: Error) => toast.error(e.message),
  })

  const deleteMutation = useMutation({
    mutationFn: api.deleteRepoCredential,
    onSuccess: () => {
      toast.success('凭据已删除')
      queryClient.invalidateQueries({ queryKey: ['repo-credentials'] })
    },
    onError: (e: Error) => toast.error(e.message),
  })

  const resetForm = () => {
    setShowForm(false)
    setPlatform('cnb')
    setOrgSlug('')
    setAccessToken('')
    setApiBase('')
    setName('')
    setSubmitting(false)
  }

  const handleSubmit = async () => {
    if (!orgSlug.trim()) {
      toast.error('请填写组织/用户名')
      return
    }
    if (!accessToken.trim()) {
      toast.error('请填写 Access Token')
      return
    }
    setSubmitting(true)
    saveMutation.mutate({
      platform,
      org_slug: orgSlug.trim(),
      access_token: accessToken.trim(),
      api_base: apiBase.trim(),
      name: name.trim(),
    })
  }

  const handleDelete = (id: number) => {
    if (!confirm('确定删除此凭据？')) return
    deleteMutation.mutate(id)
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">仓库凭据</h2>
          <p className="text-muted-foreground">
            管理 Git 仓库访问凭据，clone 私有仓库时自动嵌入认证信息
          </p>
        </div>
        <button
          onClick={() => setShowForm(v => !v)}
          className="inline-flex items-center gap-1.5 rounded-lg bg-primary px-3 py-2 text-sm text-primary-foreground hover:bg-primary/90"
        >
          <Plus className="h-4 w-4" />
          添加凭据
        </button>
      </div>

      {/* 添加/编辑表单 */}
      {showForm && (
        <div className="rounded-xl border bg-card p-5 space-y-4">
          <h3 className="font-medium flex items-center gap-2">
            <Key className="h-4 w-4 text-primary" />
            新增仓库凭据
          </h3>

          <div className="grid gap-4 sm:grid-cols-2">
            {/* 平台 */}
            <div className="space-y-1.5">
              <label className="text-sm font-medium">仓库平台</label>
              <select
                value={platform}
                onChange={e => setPlatform(e.target.value)}
                className="w-full rounded-lg border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
              >
                {PLATFORM_OPTIONS.map(opt => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>

            {/* 组织/用户名 */}
            <div className="space-y-1.5">
              <label className="text-sm font-medium">组织 / 用户名</label>
              <input
                type="text"
                value={orgSlug}
                onChange={e => setOrgSlug(e.target.value)}
                placeholder="例如: openchiip"
                className="w-full rounded-lg border bg-background px-3 py-2 text-sm placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>

            {/* Access Token */}
            <div className="space-y-1.5 sm:col-span-2">
              <label className="text-sm font-medium">Access Token</label>
              <input
                type="password"
                value={accessToken}
                onChange={e => setAccessToken(e.target.value)}
                placeholder="输入仓库访问令牌（存储时加密）"
                className="w-full rounded-lg border bg-background px-3 py-2 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>

            {/* 备注名称 */}
            <div className="space-y-1.5">
              <label className="text-sm font-medium">备注名称 <span className="text-muted-foreground font-normal">(可选)</span></label>
              <input
                type="text"
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder="例如: 公司主仓库"
                className="w-full rounded-lg border bg-background px-3 py-2 text-sm placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>

            {/* API Base */}
            <div className="space-y-1.5">
              <label className="text-sm font-medium">API Base URL <span className="text-muted-foreground font-normal">(可选)</span></label>
              <input
                type="text"
                value={apiBase}
                onChange={e => setApiBase(e.target.value)}
                placeholder="自托管仓库的 API 地址"
                className="w-full rounded-lg border bg-background px-3 py-2 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <button
              onClick={handleSubmit}
              disabled={submitting}
              className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
            >
              {submitting ? '保存中...' : '保存凭据'}
            </button>
            <button
              onClick={resetForm}
              className="rounded-lg border px-4 py-2 text-sm text-muted-foreground hover:bg-accent"
            >
              取消
            </button>
          </div>
        </div>
      )}

      {/* 凭据列表 */}
      {isLoading ? (
        <div className="text-center py-12 text-muted-foreground">加载中...</div>
      ) : credentials.length === 0 ? (
        <div className="rounded-xl border border-dashed bg-muted/30 p-8 text-center">
          <GitBranch className="h-8 w-8 text-muted-foreground mx-auto mb-3" />
          <p className="text-muted-foreground mb-1">暂无仓库凭据</p>
          <p className="text-xs text-muted-foreground">
            添加凭据后，clone 私有仓库时将自动嵌入认证信息
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {credentials.map(cred => (
            <div
              key={cred.id}
              className="rounded-xl border bg-card p-4 flex items-center gap-4"
            >
              {/* 平台图标 */}
              <div className={`flex h-10 w-10 items-center justify-center rounded-lg text-white font-bold text-sm shrink-0 ${PLATFORM_COLORS[cred.platform] || 'bg-gray-500'}`}>
                {cred.platform === 'cnb' ? 'CNB' : cred.platform[0].toUpperCase()}
              </div>

              {/* 信息 */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className="font-medium text-sm">{cred.platform}</span>
                  <span className="text-muted-foreground text-sm">/</span>
                  <span className="font-mono text-sm truncate">{cred.org_slug}</span>
                  {cred.name && (
                    <span className="text-xs text-muted-foreground bg-muted px-1.5 py-0.5 rounded">
                      {cred.name}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-3 mt-1 text-xs text-muted-foreground">
                  <span className="font-mono">
                    Token: {cred.token_hint || '(未设置)'}
                  </span>
                  <span>更新于 {cred.updated_at}</span>
                </div>
              </div>

              {/* 删除按钮 */}
              <button
                onClick={() => handleDelete(cred.id)}
                className="flex items-center gap-1 rounded-lg border border-red-200 px-2.5 py-1.5 text-xs text-red-600 hover:bg-red-50 transition-colors shrink-0"
              >
                <Trash2 className="h-3.5 w-3.5" />
                删除
              </button>
            </div>
          ))}
        </div>
      )}

      {/* 说明 */}
      <div className="rounded-xl border bg-blue-50 p-4">
        <div className="flex gap-2">
          <AlertCircle className="h-4 w-4 text-blue-600 mt-0.5 shrink-0" />
          <div className="text-xs text-blue-700 space-y-1">
            <p><strong>工作原理：</strong>运行时收到任务委派时，会根据仓库 URL 的域名和组织名匹配本地凭据，将 Token 嵌入 clone 地址（<code className="bg-blue-100 px-1 rounded">https://token@host/org/repo</code>）。</p>
            <p><strong>安全说明：</strong>Token 使用 Fernet 加密存储，密钥由本机 machine-id 派生，仅本机可解密。</p>
          </div>
        </div>
      </div>
    </div>
  )
}
